local DyeStuffMaker = {}
local PRODUCTS = {
    weld_yellow = { name = "Rumeno barvilo weld", weldCost = 2, alumCost = 1, time = 2, cost = 18, colorStrength = 30, description = "Rumeno barvilo iz rastline weld." },
    woad_blue = { name = "Modro barvilo woad", woadCost = 2, alumCost = 1, time = 3, cost = 45, colorStrength = 45, prestige = 1, description = "Modro barvilo iz rastline woad." },
    madder_red = { name = "Rdeče barvilo madder", madderCost = 2, alumCost = 1, time = 4, cost = 90, colorStrength = 60, prestige = 2, happiness = 1, description = "Rdeče barvilo iz korenine madder." },
    cochineal_crimson = { name = "Karmin iz košeniljke", cochinealCost = 2, alumCost = 1, time = 6, cost = 220, colorStrength = 80, prestige = 5, happiness = 2, description = "Karmin iz sušenih košeniljk za plemiče." },
    silver_mordant_dye = { name = "Srebrno fiksirano barvilo", cochinealCost = 2, silverCost = 1, alumCost = 1, time = 9, cost = 480, colorStrength = 92, prestige = 11, happiness = 3, description = "Barvilo s srebrnim fiksativom za intenzivne barve." },
    royal_purple_dye = { name = "Kraljevski purpur", cochinealCost = 3, madderCost = 2, goldCost = 1, silverCost = 1, jewelCost = 1, alumCost = 2, time = 14, cost = 1500, colorStrength = 100, prestige = 38, happiness = 9, description = "Veliki kraljevski purpur z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Barvilarsna delavnica", cost = { gold = 280, wood = 130, stone = 200 }, upkeep = 7, qualityBonus = 5 },
    dye_vat_house = { name = "Barvilna kadi", cost = { gold = 950, wood = 250, stone = 400, alum = 8 }, upkeep = 23, qualityBonus = 18 },
    drying_room = { name = "Sušilnica", cost = { gold = 2300, wood = 350, stone = 600, silver = 30, weld = 8 }, upkeep = 58, qualityBonus = 30 },
    royal_dye_atelier = { name = "Kraljevski atelje barvil", cost = { gold = 9500, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 190, qualityBonus = 55, prestigeBonus = 40 },
}
DyeStuffMaker.weldStock = 16; DyeStuffMaker.woadStock = 14; DyeStuffMaker.madderStock = 14; DyeStuffMaker.cochinealStock = 12; DyeStuffMaker.alumStock = 14; DyeStuffMaker.silverStock = 8; DyeStuffMaker.goldStock = 6; DyeStuffMaker.jewelStock = 6
DyeStuffMaker.productStock = {}; DyeStuffMaker.buildings = {}; DyeStuffMaker.maker = nil; DyeStuffMaker.activeMaking = {}; DyeStuffMaker.totalProducts = 0; DyeStuffMaker.dayTimer = 0
function DyeStuffMaker.init() DyeStuffMaker.weldStock=16; DyeStuffMaker.woadStock=14; DyeStuffMaker.madderStock=14; DyeStuffMaker.cochinealStock=12; DyeStuffMaker.alumStock=14; DyeStuffMaker.silverStock=8; DyeStuffMaker.goldStock=6; DyeStuffMaker.jewelStock=6; DyeStuffMaker.productStock={}; DyeStuffMaker.buildings={}; DyeStuffMaker.maker=nil; DyeStuffMaker.activeMaking={}; DyeStuffMaker.totalProducts=0; DyeStuffMaker.dayTimer=0; print("[DyeStuffMaker] Royal Dye-Stuff Maker System initialized (6 products, 4 buildings)") end
function DyeStuffMaker.hireMaker(n,s) s=s or math.random(50,90); local c=510+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; DyeStuffMaker.maker={name=n or ("Barvilar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Barvilar najet: %s (spretnost: %d)",DyeStuffMaker.maker.name,s),"success") end; return true end
function DyeStuffMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function DyeStuffMaker.build(id) local ok,e=DyeStuffMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(DyeStuffMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function DyeStuffMaker.getQualityBonus() local b=0; for _,bd in ipairs(DyeStuffMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function DyeStuffMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.weldCost and DyeStuffMaker.weldStock<(d.weldCost or 0) then return false,"Premalo welda" end; if d.woadCost and DyeStuffMaker.woadStock<(d.woadCost or 0) then return false,"Premalo woad" end; if d.madderCost and DyeStuffMaker.madderStock<(d.madderCost or 0) then return false,"Premalo madder" end; if d.cochinealCost and DyeStuffMaker.cochinealStock<(d.cochinealCost or 0) then return false,"Premalo košeniljke" end; if d.alumCost and DyeStuffMaker.alumStock<(d.alumCost or 0) then return false,"Premalo aluna" end; if d.silverCost and DyeStuffMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and DyeStuffMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and DyeStuffMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #DyeStuffMaker.buildings==0 then return false,"Potrebna delavnica" end; if not DyeStuffMaker.maker then return false,"Potreben barvilar" end; return true end
function DyeStuffMaker.make(pt,qty) qty=qty or 5; local ok,e=DyeStuffMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.weldCost then DyeStuffMaker.weldStock=DyeStuffMaker.weldStock-d.weldCost*qty end; if d.woadCost then DyeStuffMaker.woadStock=DyeStuffMaker.woadStock-d.woadCost*qty end; if d.madderCost then DyeStuffMaker.madderStock=DyeStuffMaker.madderStock-d.madderCost*qty end; if d.cochinealCost then DyeStuffMaker.cochinealStock=DyeStuffMaker.cochinealStock-d.cochinealCost*qty end; if d.alumCost then DyeStuffMaker.alumStock=DyeStuffMaker.alumStock-d.alumCost*qty end; if d.silverCost then DyeStuffMaker.silverStock=DyeStuffMaker.silverStock-d.silverCost*qty end; if d.goldCost then DyeStuffMaker.goldStock=DyeStuffMaker.goldStock-d.goldCost*qty end; if d.jewelCost then DyeStuffMaker.jewelStock=DyeStuffMaker.jewelStock-d.jewelCost*qty end; local t=d.time; if DyeStuffMaker.maker then t=math.max(1,t-math.floor(DyeStuffMaker.maker.skill/12)) end; table.insert(DyeStuffMaker.activeMaking,{id="dye_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,colorStrength=d.colorStrength or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function DyeStuffMaker.completeMaking(m) local q=1.0+(DyeStuffMaker.getQualityBonus()/100); if DyeStuffMaker.maker then q=q+(DyeStuffMaker.maker.skill/180) end; q=math.min(2.0,q); DyeStuffMaker.productStock[m.productType]=(DyeStuffMaker.productStock[m.productType] or 0)+m.quantity; DyeStuffMaker.totalProducts=DyeStuffMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if DyeStuffMaker.maker then DyeStuffMaker.maker.itemsMade=DyeStuffMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then DyeStuffMaker.maker.skill=math.min(100,DyeStuffMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Barvilo izdelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"dyestuff.completed",{productName=m.productName,colorStrength=m.colorStrength}) end end
function DyeStuffMaker.update(dt) if not _G.state then return end; DyeStuffMaker.dayTimer=DyeStuffMaker.dayTimer+dt; if DyeStuffMaker.dayTimer>=30 then DyeStuffMaker.dayTimer=0; for i=#DyeStuffMaker.activeMaking,1,-1 do local m=DyeStuffMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then DyeStuffMaker.completeMaking(m); table.remove(DyeStuffMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(DyeStuffMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if DyeStuffMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function DyeStuffMaker.getStats() return {weldStock=DyeStuffMaker.weldStock,woadStock=DyeStuffMaker.woadStock,madderStock=DyeStuffMaker.madderStock,cochinealStock=DyeStuffMaker.cochinealStock,alumStock=DyeStuffMaker.alumStock,silverStock=DyeStuffMaker.silverStock,goldStock=DyeStuffMaker.goldStock,jewelStock=DyeStuffMaker.jewelStock,productStock=DyeStuffMaker.productStock,numBuildings=#DyeStuffMaker.buildings,hasMaker=DyeStuffMaker.maker~=nil,makerName=DyeStuffMaker.maker and DyeStuffMaker.maker.name or "—",makerSkill=DyeStuffMaker.maker and DyeStuffMaker.maker.skill or 0,activeMaking=#DyeStuffMaker.activeMaking,totalProducts=DyeStuffMaker.totalProducts} end
return DyeStuffMaker
